# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorLog {
  error: Error;
  errorInfo: ErrorInfo;
  timestamp: Date;
  componentStack: string;
}

interface Props {
  children: ReactNode;
  fallback?: ReactNode | ((props: FallbackProps) => ReactNode);
  onError?: (log: ErrorLog) => void;
  onReset?: () => void;
  resetKeys?: unknown[];
  isolate?: boolean;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  errorCount: number;
}

export interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  resetError: () => void;
  errorCount: number;
}

// ─── Logger ───────────────────────────────────────────────────────────────────

class ErrorLogger {
  private static logs: ErrorLog[] = [];

  static log(error: Error, errorInfo: ErrorInfo): ErrorLog {
    const entry: ErrorLog = {
      error,
      errorInfo,
      timestamp: new Date(),
      componentStack: errorInfo.componentStack ?? "",
    };

    this.logs.push(entry);

    // Console output with grouping
    console.group(
      `%c⚠ React Error Boundary [${entry.timestamp.toISOString()}]`,
      "color: #ff4444; font-weight: bold;"
    );
    console.error("Error:", error.message);
    console.error("Stack:", error.stack);
    console.error("Component Stack:", entry.componentStack);
    console.groupEnd();

    return entry;
  }

  static getLogs(): ErrorLog[] {
    return [...this.logs];
  }

  static clearLogs(): void {
    this.logs = [];
  }
}

// ─── Default Fallback UI ──────────────────────────────────────────────────────

const DefaultFallback: React.FC<FallbackProps> = ({
  error,
  errorInfo,
  resetError,
  errorCount,
}) => {
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Icon */}
        <div style={styles.iconWrapper}>
          <svg
            style={styles.icon}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
          >
            <circle cx="12" cy="12" r="10" />
            <line x1="12" y1="8" x2="12" y2="12" />
            <line x1="12" y1="16" x2="12.01" y2="16" />
          </svg>
        </div>

        {/* Heading */}
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.subheading}>
          {errorCount > 1
            ? `This component has crashed ${errorCount} times.`
            : "An unexpected error occurred in this component."}
        </p>

        {/* Error message */}
        <div style={styles.errorMessage}>
          <code style={styles.errorCode}>{error.message}</code>
        </div>

        {/* Actions */}
        <div style={styles.actions}>
          <button style={styles.retryButton} onClick={resetError}>
            ↺ Try Again
          </button>
          <button
            style={styles.detailsButton}
            onClick={() => setShowDetails((v) => !v)}
          >
            {showDetails ? "Hide" : "Show"} Details
          </button>
        </div>

        {/* Collapsible details */}
        {showDetails && (
          <details style={styles.details} open>
            <summary style={styles.summary}>Stack Trace</summary>
            <pre style={styles.pre}>{error.stack}</pre>
            <summary style={styles.summary}>Component Stack</summary>
            <pre style={styles.pre}>{errorInfo.componentStack}</pre>
          </details>
        )}
      </div>
    </div>
  );
};

// ─── Error Boundary Class ─────────────────────────────────────────────────────

export class ErrorBoundary extends Component<Props, State> {
  private prevResetKeys: unknown[];

  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      errorCount: 0,
    };
    this.prevResetKeys = props.resetKeys ?? [];
  }

  // Triggered during render phase — update state to show fallback
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // Triggered after render — side effects like logging
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const log = ErrorLogger.log(error, errorInfo);

    this.setState((prev) => ({
      errorInfo,
      errorCount: prev.errorCount + 1,
    }));

    this.props.onError?.(log);
  }

  // Watch resetKeys for external reset triggers
  componentDidUpdate(prevProps: Props): void {
    const { resetKeys } = this.props;
    const { hasError } = this.state;

    if (!hasError || !resetKeys) return;

    const hasKeyChanged = resetKeys.some(
      (key, idx) => key !== this.prevResetKeys[idx]
    );

    if (hasKeyChanged) {
      this.prevResetKeys = resetKeys;
      this.resetError();
    }
  }

  resetError = (): void => {
    this.props.onReset?.();
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });
  };

  render(): ReactNode {
    const { hasError, error, errorInfo, errorCount } = this.state;
    const { children, fallback, isolate } = this.props;

    if (hasError && error && errorInfo) {
      const fallbackProps: FallbackProps = {
        error,
        errorInfo,
        resetError: this.resetError,
        errorCount,
      };

      if (typeof fallback === "function") {
        return fallback(fallbackProps);
      }

      if (fallback) {
        return fallback;
      }

      return <DefaultFallback {...fallbackProps} />;
    }

    // isolate prop wraps children in a div to contain layout impact
    return isolate ? <div>{children}</div> : children;
  }
}

// ─── Styles ───────────────────────────────────────────────────────────────────

