  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "200px",
    padding: "24px",
    fontFamily: "system-ui, -apple-system, sans-serif",
  },
  card: {
    background: "#fff",
    border: "1px solid #fee2e2",
    borderRadius: "12px",
    padding: "32px",
    maxWidth: "520px",
    width: "100%",
    boxShadow: "0 4px 24px rgba(239,68,68,0.08)",
    textAlign: "center",
  },
  iconWrapper: {
    display: "flex",
    justifyContent: "center",
    marginBottom: "16px",
  },
  icon: {
    width: "48px",
