    color: "#ef4444",
  },
  heading: {
    margin: "0 0 8px",
    fontSize: "20px",
    fontWeight: 700,
    color: "#111827",
  },
  subheading: {
    margin: "0 0 20px",
    fontSize: "14px",
    color: "#6b7280",
  },
  errorMessage: {
    background: "#fef2f2",
    border: "1px solid #fecaca",
    borderRadius: "8px",
    padding: "12px 16px",
    marginBottom: "24px",
    textAlign: "left",
  },
  errorCode: {
    fontSize: "13px",
    color: "#dc2626",
    wordBreak: "break-word",
    fontFamily: "monospace",
  },
  actions: {
    display: "flex",
    gap: "12px",
    justifyContent: "center",
    marginBottom: "16px",
  },
  retryButton: {
    background: "#ef4444",
    color: "#fff",
    border: "none",
    borderRadius: "8px",
    padding: "10px 24px",
    fontSize: "14px",
    fontWeight: 600,
    cursor: "pointer",
    transition: "background 0.2s",
  },
  detailsButton: {
    background: "transparent",
    color: "#6b7280",
    border: "1px solid #e5e7eb",
    borderRadius: "8px",
    padding: "10px 24px",
    fontSize: "14px",
    cursor: "pointer",
  },
  details: {
    textAlign: "left",
    marginTop: "16px",
  },
  summary: {
    fontSize: "12px",
    fontWeight: 600,
    color: "#374151",
    cursor: "pointer",
    marginBottom: "8px",
  },
  pre: {
    background: "#f9fafb",
    border: "1px solid #e5e7eb",
    borderRadius: "6px",
    padding: "12px",
    fontSize: "11px",
    overflowX: "auto",
    color: "#374151",
    marginBottom: "12px",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
};
