## Usage Examples

```tsx
// App.tsx
import React, { useState } from "react";
import { ErrorBoundary, FallbackProps } from "./ErrorBoundary";

// ─── Buggy component for demo ─────────────────────────────────────────────────

const BuggyCounter: React.FC = () => {
  const [count, setCount] = useState(0);

  if (count >= 3) {
    throw new Error(`Counter exceeded limit: value was ${count}`);
  }

  return (
    <div style={{ textAlign: "center", padding: "20px" }}>
      <p>Count: {count}</p>
      <button onClick={() => setCount((c) => c + 1)}>
        Increment (crashes at 3)
      </button>
    </div>
  );
};

// ─── 1. Basic usage ───────────────────────────────────────────────────────────

export const BasicExample: React.FC = () => (
  <ErrorBoundary>
    <BuggyCounter />
  </ErrorBoundary>
);

// ─── 2. Custom fallback render prop ───────────────────────────────────────────

const CustomFallback = ({ error, resetError, errorCount }: FallbackProps) => (
  <div style={{ padding: 20, border: "2px dashed red", borderRadius: 8 }}>
    <h3>💥 Custom Error UI</h3>
    <p>{error.message}</p>
    <p>Crashed {errorCount} time(s)</p>
    <button onClick={resetError}>Retry</button>
  </div>
);

export const CustomFallbackExample: React.FC = () => (
  <ErrorBoundary fallback={(props) => <CustomFallback {...props} />}>
    <BuggyCounter />
  </ErrorBoundary>
);

// ─── 3. External reset via resetKeys ─────────────────────────────────────────

export const ResetKeysExample: React.FC = () => {
  const [resetKey, setResetKey] = useState(0);

  return (
    <div>
      <button onClick={() => setResetKey((k) => k + 1)}>
        Reset from outside
      </button>
      <ErrorBoundary
        resetKeys={[resetKey]}
        onReset={() => console.log("Boundary was reset")}
      >
        <BuggyCounter />
      </ErrorBoundary>
    </div>
  );
};

// ─── 4. Error logging callback ────────────────────────────────────────────────

export const LoggingExample: React.FC = () => (
  <ErrorBoundary
    onError={({ error, timestamp }) => {
      // Send to your monitoring service
      console.log(`[${timestamp.toISOString()}] Sending to Sentry:`, error);
    }}
  >
    <BuggyCounter />
  </ErrorBoundary>
);

// ─── 5. Nested boundaries (isolate sections) ──────────────────────────────────

export const NestedExample: React.FC = () => (
  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
    <ErrorBoundary isolate>
      <BuggyCounter />
    </ErrorBoundary>
    <ErrorBoundary isolate>
      <p>This section is unaffected by the left crash ✅</p>
    </ErrorBoundary>
  </div>
);
```

